"""Intent tests for M1-T19: risk.summary_stats, the whole-period summary (RISK-04, TC-07)."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _vol(data: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _by_ticker(summaries: tuple[TickerSummary, ...]) -> dict[str, TickerSummary]:
    return {s.ticker: s for s in summaries}


@pytest.mark.intent
def test_tc07_one_summary_per_ticker(golden):
    data, expected = golden("risk", "TC-07")
    result = summary_stats(_vol(data["vol"]))
    assert isinstance(result, tuple)
    assert all(isinstance(s, TickerSummary) for s in result)
    assert [s.ticker for s in result] == [row["ticker"] for row in expected["summary"]]


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_figures(golden, field):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"])))
    for row in expected["summary"]:
        actual = getattr(got[row["ticker"]], field)
        assert actual == pytest.approx(row[field], abs=expected["tol"]), row["ticker"]


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"])))
    flat = next(row for row in expected["summary"] if row["ann_vol"] == 0)
    assert got[flat["ticker"]].ann_vol == pytest.approx(0.0, abs=expected["tol"])
    assert got[flat["ticker"]].sharpe == pytest.approx(flat["sharpe"], abs=expected["tol"])


@pytest.mark.intent
def test_tc07_last_rolling_vol(golden):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"])))
    for row in expected["summary"]:
        last_vol = got[row["ticker"]].last_vol
        assert last_vol is not None, row["ticker"]
        assert last_vol == pytest.approx(row["last_vol"], abs=expected["tol"]), row["ticker"]


@pytest.mark.intent
def test_explicit_periods_per_year_252_matches_default(golden):
    data, expected = golden("risk", "TC-07")
    got = _by_ticker(summary_stats(_vol(data["vol"]), periods_per_year=252))
    for row in expected["summary"]:
        summary = got[row["ticker"]]
        assert summary.ann_return == pytest.approx(row["ann_return"], abs=expected["tol"])
        assert summary.ann_vol == pytest.approx(row["ann_vol"], abs=expected["tol"])


@pytest.mark.intent
def test_fewer_than_two_returns_is_rejected(golden):
    data, _ = golden("risk", "TC-07")
    vol = data["vol"]
    short = {
        "returns": {
            "base_date": vol["returns"]["base_date"],
            "dates": vol["returns"]["dates"][:1],
            "tickers": vol["returns"]["tickers"],
            "values": {t: v[:1] for t, v in vol["returns"]["values"].items()},
        },
        "window": vol["window"],
        "annualized": vol["annualized"],
        "values": {t: v[:1] for t, v in vol["values"].items()},
    }
    with pytest.raises(ValueError, match=r"(?i)two|2|return"):
        summary_stats(_vol(short))

